#include <stdio.h>
#include <stdbool.h>

#define MAXS 1005

static bool adj[MAXS][MAXS];

int main(void) {
    int s, t;
    if (scanf("%d %d", &s, &t) != 2) return 0;

    for (int i = 0; i < t; i++) {
        int u, v;
        scanf("%d %d", &u, &v);
        adj[u][v] = true;
        adj[v][u] = true;
    }

    int p;
    if (scanf("%d", &p) != 1) return 0;

    int valid_tours = 0;
    for (int i = 0; i < p; i++) {
        int n;
        scanf("%d", &n);
        int prev;
        scanf("%d", &prev);
        bool possible = true;
        for (int j = 1; j < n; j++) {
            int curr;
            scanf("%d", &curr);
            if (possible && !adj[prev][curr]) {
                possible = false;
            }
            prev = curr;
        }
        if (possible) {
            valid_tours++;
        }
    }

    printf("%d\n", valid_tours);

    return 0;
}
